import java.io.*;
import java.util.*;
import java.util.jar.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;

/** Exact native-boundary discovery and small ASM generation utilities. */
public final class HungAutoAttackNativeBuilder implements Opcodes {
    static String n(String tail) { StringBuilder b=new StringBuilder(); while(b.length()+tail.length()<100)b.append('i'); return b.append(tail).toString(); }
    static void require(boolean b,String s) { if(!b)throw new IllegalStateException(s); }
    static ClassNode parse(byte[] b) { require(b!=null,"missing class"); ClassNode c=new ClassNode(ASM9);new ClassReader(b).accept(c,0);return c; }
    static byte[] bytes(ClassNode c) { ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray(); }
    static MethodNode method(ClassNode c,String n,String d) { for(MethodNode m:c.methods)if(m.name.equals(n)&&m.desc.equals(d))return m;throw new IllegalStateException("missing "+c.name+"."+n+d); }
    static List<AbstractInsnNode> real(MethodNode m) { List<AbstractInsnNode> r=new ArrayList<AbstractInsnNode>();for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()>=0)r.add(i);return r; }
    static byte[] read(InputStream i)throws Exception { try {ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int k;while((k=i.read(b))!=-1)o.write(b,0,k);return o.toByteArray();}finally{i.close();} }
    static AbstractInsnNode next(AbstractInsnNode i) { do{i=i.getNext();}while(i!=null&&i.getOpcode()<0);return i; }
    static AbstractInsnNode previous(AbstractInsnNode i) { do{i=i.getPrevious();}while(i!=null&&i.getOpcode()<0);return i; }
    static boolean field(AbstractInsnNode i,int op,String o,String n,String d) { if(!(i instanceof FieldInsnNode)||i.getOpcode()!=op)return false;FieldInsnNode f=(FieldInsnNode)i;return (o==null||o.equals(f.owner))&&(n==null||n.equals(f.name))&&(d==null||d.equals(f.desc)); }
    static boolean call(AbstractInsnNode i,String o,String n,String d) { if(!(i instanceof MethodInsnNode))return false;MethodInsnNode m=(MethodInsnNode)i;return(o==null||o.equals(m.owner))&&(n==null||n.equals(m.name))&&(d==null||d.equals(m.desc)); }
    static AbstractInsnNode push(int i) { return i>=-1&&i<=5?new InsnNode(ICONST_0+i):i>=-128&&i<=127?new IntInsnNode(BIPUSH,i):i>=-32768&&i<=32767?new IntInsnNode(SIPUSH,i):new LdcInsnNode(i); }
    static int integer(AbstractInsnNode i) { int op=i.getOpcode();if(op>=ICONST_M1&&op<=ICONST_5)return op-ICONST_0;if(i instanceof IntInsnNode)return((IntInsnNode)i).operand;if(i instanceof LdcInsnNode&&((LdcInsnNode)i).cst instanceof Integer)return((Integer)((LdcInsnNode)i).cst).intValue();return Integer.MIN_VALUE; }
    static void invoke(InsnList l,int op,String o,String n,String d) { l.add(new MethodInsnNode(op,o,n,d,op==INVOKEINTERFACE)); }
    static MethodNode create(ClassNode c,int access,String name,String desc) { MethodNode m=new MethodNode(ASM9,access,name,desc,null,null);c.methods.add(m);return m; }
    static ClassNode create(String name,String... interfaces) { ClassNode c=new ClassNode(ASM9);c.version=V1_4;c.access=ACC_PUBLIC|ACC_FINAL;c.name=name;c.superName="java/lang/Object";c.interfaces.addAll(Arrays.asList(interfaces));MethodNode m=create(c,ACC_PUBLIC,"<init>","()V");m.instructions.add(new VarInsnNode(ALOAD,0));invoke(m.instructions,INVOKESPECIAL,"java/lang/Object","<init>","()V");m.instructions.add(new InsnNode(RETURN));return c; }
    static java.lang.reflect.Field resolveField(Class<?> c,String n,String d){for(Class<?> k=c;k!=null;k=k.getSuperclass())for(java.lang.reflect.Field f:k.getDeclaredFields())if(f.getName().equals(n)&&Type.getDescriptor(f.getType()).equals(d))return f;return null;}
    static java.lang.reflect.Method resolveMethod(Class<?> c,String n,String d){for(Class<?> k=c;k!=null;k=k.getSuperclass()){for(java.lang.reflect.Method m:k.getDeclaredMethods())if(m.getName().equals(n)&&Type.getMethodDescriptor(m).equals(d))return m;for(Class<?> i:k.getInterfaces()){java.lang.reflect.Method hit=resolveMethod(i,n,d);if(hit!=null)return hit;}}return null;}
    public static void main(String[] args)throws Exception {
        if(args.length==3&&"--link".equals(args[0])){JarFile jar=new JarFile(args[1]);java.net.URLClassLoader loader=new java.net.URLClassLoader(new java.net.URL[]{new File(args[1]).toURI().toURL(),new File(args[2]).toURI().toURL()},null);int count=0;try{for(Enumeration<JarEntry> e=jar.entries();e.hasMoreElements();){String name=e.nextElement().getName();if(!name.endsWith(".class"))continue;Class<?> c=Class.forName(name.substring(0,name.length()-6).replace('/','.'),false,loader);c.getDeclaredFields();c.getDeclaredMethods();c.getDeclaredConstructors();if(name.startsWith("luna/generated/HungAutoAttack")||name.startsWith("luna/features/AutoAttack")){ClassNode code=parse(read(jar.getInputStream(jar.getJarEntry(name))));for(MethodNode m:code.methods)for(AbstractInsnNode ins:real(m)){if(ins instanceof FieldInsnNode){FieldInsnNode f=(FieldInsnNode)ins;java.lang.reflect.Field target=resolveField(Class.forName(f.owner.replace('/','.'),false,loader),f.name,f.desc);require(target!=null,"unresolved adapter field "+f.owner+"."+f.name+f.desc);require(java.lang.reflect.Modifier.isStatic(target.getModifiers())==(f.getOpcode()==GETSTATIC||f.getOpcode()==PUTSTATIC),"adapter field static mismatch");require(java.lang.reflect.Modifier.isPublic(target.getModifiers())||code.name.equals(f.owner),"adapter field access "+f.name);}else if(ins instanceof MethodInsnNode){MethodInsnNode q=(MethodInsnNode)ins;if(q.name.equals("<init>")){Class<?> owner=Class.forName(q.owner.replace('/','.'),false,loader);boolean found=false;for(java.lang.reflect.Constructor<?> ctor:owner.getDeclaredConstructors())if(Type.getConstructorDescriptor(ctor).equals(q.desc))found=true;require(found,"unresolved adapter constructor "+q.owner+q.desc);}else{java.lang.reflect.Method target=resolveMethod(Class.forName(q.owner.replace('/','.'),false,loader),q.name,q.desc);require(target!=null,"unresolved adapter method "+q.owner+"."+q.name+q.desc);require(java.lang.reflect.Modifier.isStatic(target.getModifiers())==(q.getOpcode()==INVOKESTATIC),"adapter method static mismatch "+q.name);require(java.lang.reflect.Modifier.isPublic(target.getModifiers())||code.name.equals(q.owner),"adapter method access "+q.name);}}}}count++;}}finally{loader.close();jar.close();}System.out.println("LINK_PASS classes="+count);return;}
        JarFile j=new JarFile(args[0]);for(Enumeration<JarEntry> e=j.entries();e.hasMoreElements();){JarEntry z=e.nextElement();if(!z.getName().endsWith(".class"))continue;ClassNode c=parse(read(j.getInputStream(z)));boolean hit=false;for(MethodNode m:c.methods)for(AbstractInsnNode i:real(m))if(i instanceof MethodInsnNode&&(((MethodInsnNode)i).owner.indexOf("TextField")>=0||((MethodInsnNode)i).owner.indexOf("TextBox")>=0))hit=true;if(hit){System.out.println("INPUT "+c.name);for(FieldNode f:c.fields)System.out.println("FIELD "+f.name+" "+f.desc);for(MethodNode m:c.methods)System.out.println("METHOD "+m.name+m.desc);}}j.close();
    }
}
